# T3 Chat colors for the shell and terminal, generated by scripts/t3_chat_theme.py.
# Light by default. `t3-theme dark` switches every shell and app it knows, and remembers the
# choice; `t3-theme light` switches back. T3_CHAT_MODE=light|dark overrides the saved choice.
_t3_chat_mode_file="${XDG_CONFIG_HOME:-$HOME/.config}/t3-chat/mode"

_t3_chat_mode() {
    local mode="${T3_CHAT_MODE:-}"
    [ -n "$mode" ] || [ ! -r "$_t3_chat_mode_file" ] || read -r mode < "$_t3_chat_mode_file"
    case "$mode" in dark) echo dark ;; *) echo light ;; esac
}

# Recolor this terminal (xfce4-terminal, Ghostty, Windows Terminal, tmux...) and zsh's highlighting.
_t3_chat_apply() {
    [ -z "${ZSH_VERSION:-}" ] || typeset -gA ZSH_HIGHLIGHT_STYLES
    case "$(_t3_chat_mode)" in
        light)
            _t3_chat_osc='\033]4;0;#000000\007\033]4;1;#cd3131\007\033]4;2;#107c10\007\033]4;3;#949800\007\033]4;4;#0451a5\007\033]4;5;#bc05bc\007\033]4;6;#0598bc\007\033]4;7;#555555\007\033]4;8;#666666\007\033]4;9;#cd3131\007\033]4;10;#14ce14\007\033]4;11;#b5ba00\007\033]4;12;#0451a5\007\033]4;13;#bc05bc\007\033]4;14;#0598bc\007\033]4;15;#a5a5a5\007\033]10;#501854\007\033]11;#fdf7fd\007\033]12;#db2777\007'
            _t3_chat_suggestion='fg=#8b5f90'
            if [ -n "${ZSH_VERSION:-}" ]; then
                ZSH_HIGHLIGHT_STYLES[default]='none'
                ZSH_HIGHLIGHT_STYLES[unknown-token]='fg=#f7086c'
                ZSH_HIGHLIGHT_STYLES[reserved-word]='fg=#d32a61'
                ZSH_HIGHLIGHT_STYLES[alias]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[suffix-alias]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[global-alias]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[builtin]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[function]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[command]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[precommand]='fg=#693acf,underline'
                ZSH_HIGHLIGHT_STYLES[hashed-command]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[arg0]='fg=#693acf'
                ZSH_HIGHLIGHT_STYLES[commandseparator]='fg=#636363'
                ZSH_HIGHLIGHT_STYLES[redirection]='fg=#636363'
                ZSH_HIGHLIGHT_STYLES[path]='underline'
                ZSH_HIGHLIGHT_STYLES[globbing]='fg=#17a5af'
                ZSH_HIGHLIGHT_STYLES[history-expansion]='fg=#17a5af'
                ZSH_HIGHLIGHT_STYLES[single-hyphen-option]='fg=#d47628'
                ZSH_HIGHLIGHT_STYLES[double-hyphen-option]='fg=#d47628'
                ZSH_HIGHLIGHT_STYLES[single-quoted-argument]='fg=#199f43'
                ZSH_HIGHLIGHT_STYLES[double-quoted-argument]='fg=#199f43'
                ZSH_HIGHLIGHT_STYLES[dollar-quoted-argument]='fg=#199f43'
                ZSH_HIGHLIGHT_STYLES[back-quoted-argument]='fg=#16a994'
                ZSH_HIGHLIGHT_STYLES[dollar-double-quoted-argument]='fg=#d47628'
                ZSH_HIGHLIGHT_STYLES[back-double-quoted-argument]='fg=#16a994'
                ZSH_HIGHLIGHT_STYLES[back-dollar-quoted-argument]='fg=#16a994'
                ZSH_HIGHLIGHT_STYLES[assign]='fg=#d47628'
                ZSH_HIGHLIGHT_STYLES[comment]='fg=#737373'
                ZSH_HIGHLIGHT_STYLES[named-fd]='fg=#1ca1c7'
                ZSH_HIGHLIGHT_STYLES[numeric-fd]='fg=#1ca1c7'
            fi
            ;;
        dark)
            _t3_chat_osc='\033]4;0;#000000\007\033]4;1;#cd3131\007\033]4;2;#0dbc79\007\033]4;3;#e5e510\007\033]4;4;#2472c8\007\033]4;5;#bc3fbc\007\033]4;6;#11a8cd\007\033]4;7;#e5e5e5\007\033]4;8;#666666\007\033]4;9;#f14c4c\007\033]4;10;#23d18b\007\033]4;11;#f5f543\007\033]4;12;#3b8eea\007\033]4;13;#d670d6\007\033]4;14;#29b8db\007\033]4;15;#e5e5e5\007\033]10;#f9f8fb\007\033]11;#1f1a24\007\033]12;#db2777\007'
            _t3_chat_suggestion='fg=#968d9f'
            if [ -n "${ZSH_VERSION:-}" ]; then
                ZSH_HIGHLIGHT_STYLES[default]='none'
                ZSH_HIGHLIGHT_STYLES[unknown-token]='fg=#9d174d'
                ZSH_HIGHLIGHT_STYLES[reserved-word]='fg=#ff678d'
                ZSH_HIGHLIGHT_STYLES[alias]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[suffix-alias]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[global-alias]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[builtin]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[function]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[command]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[precommand]='fg=#9d6afb,underline'
                ZSH_HIGHLIGHT_STYLES[hashed-command]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[arg0]='fg=#9d6afb'
                ZSH_HIGHLIGHT_STYLES[commandseparator]='fg=#636363'
                ZSH_HIGHLIGHT_STYLES[redirection]='fg=#636363'
                ZSH_HIGHLIGHT_STYLES[path]='underline'
                ZSH_HIGHLIGHT_STYLES[globbing]='fg=#64d1db'
                ZSH_HIGHLIGHT_STYLES[history-expansion]='fg=#64d1db'
                ZSH_HIGHLIGHT_STYLES[single-hyphen-option]='fg=#ffa359'
                ZSH_HIGHLIGHT_STYLES[double-hyphen-option]='fg=#ffa359'
                ZSH_HIGHLIGHT_STYLES[single-quoted-argument]='fg=#5ecc71'
                ZSH_HIGHLIGHT_STYLES[double-quoted-argument]='fg=#5ecc71'
                ZSH_HIGHLIGHT_STYLES[dollar-quoted-argument]='fg=#5ecc71'
                ZSH_HIGHLIGHT_STYLES[back-quoted-argument]='fg=#61d5c0'
                ZSH_HIGHLIGHT_STYLES[dollar-double-quoted-argument]='fg=#ffa359'
                ZSH_HIGHLIGHT_STYLES[back-double-quoted-argument]='fg=#61d5c0'
                ZSH_HIGHLIGHT_STYLES[back-dollar-quoted-argument]='fg=#61d5c0'
                ZSH_HIGHLIGHT_STYLES[assign]='fg=#ffa359'
                ZSH_HIGHLIGHT_STYLES[comment]='fg=#737373'
                ZSH_HIGHLIGHT_STYLES[named-fd]='fg=#68cdf2'
                ZSH_HIGHLIGHT_STYLES[numeric-fd]='fg=#68cdf2'
            fi
            ;;
    esac
    ZSH_AUTOSUGGEST_HIGHLIGHT_STYLE="$_t3_chat_suggestion"
    # VS Code's terminal follows the VS Code theme; dumb terminals and the Linux console get nothing.
    case "${TERM:-dumb}" in dumb | linux) return 0 ;; esac
    if [ -t 1 ] && [ "${TERM_PROGRAM:-}" != vscode ] && [ -z "${NO_COLOR:-}" ]; then
        printf '%b' "$_t3_chat_osc"
    fi
}

# Saved settings of apps that cannot be recolored from the shell.
_t3_chat_apps() {
    local btop="${XDG_CONFIG_HOME:-$HOME/.config}/btop/btop.conf"
    if [ -w "$btop" ] && grep -q '^color_theme = ' "$btop"; then
        sed -i.t3bak "s/^color_theme = .*/color_theme = \"t3-chat-$1\"/" "$btop" && rm -f "$btop.t3bak"
    fi
    if command -v xfconf-query >/dev/null 2>&1 && xfconf-query -c xfce4-terminal -l >/dev/null 2>&1; then
        case "$1" in
            light)
                xfconf-query -c xfce4-terminal -p /color-foreground -n -t string -s '#501854'
                xfconf-query -c xfce4-terminal -p /color-background -n -t string -s '#fdf7fd'
                xfconf-query -c xfce4-terminal -p /color-cursor-use-default -n -t bool -s 'false'
                xfconf-query -c xfce4-terminal -p /color-cursor -n -t string -s '#db2777'
                xfconf-query -c xfce4-terminal -p /color-cursor-foreground -n -t string -s '#fdf7fd'
                xfconf-query -c xfce4-terminal -p /color-selection-use-default -n -t bool -s 'false'
                xfconf-query -c xfce4-terminal -p /color-selection -n -t string -s '#501854'
                xfconf-query -c xfce4-terminal -p /color-selection-background -n -t string -s '#f1c4e6'
                xfconf-query -c xfce4-terminal -p /color-bold-use-default -n -t bool -s 'true'
                xfconf-query -c xfce4-terminal -p /tab-activity-color -n -t string -s '#db2777'
                xfconf-query -c xfce4-terminal -p /color-palette -n -t string -s '#000000;#cd3131;#107c10;#949800;#0451a5;#bc05bc;#0598bc;#555555;#666666;#cd3131;#14ce14;#b5ba00;#0451a5;#bc05bc;#0598bc;#a5a5a5'
                ;;
            dark)
                xfconf-query -c xfce4-terminal -p /color-foreground -n -t string -s '#f9f8fb'
                xfconf-query -c xfce4-terminal -p /color-background -n -t string -s '#1f1a24'
                xfconf-query -c xfce4-terminal -p /color-cursor-use-default -n -t bool -s 'false'
                xfconf-query -c xfce4-terminal -p /color-cursor -n -t string -s '#db2777'
                xfconf-query -c xfce4-terminal -p /color-cursor-foreground -n -t string -s '#1f1a24'
                xfconf-query -c xfce4-terminal -p /color-selection-use-default -n -t bool -s 'false'
                xfconf-query -c xfce4-terminal -p /color-selection -n -t string -s '#f9f8fb'
                xfconf-query -c xfce4-terminal -p /color-selection-background -n -t string -s '#362d3d'
                xfconf-query -c xfce4-terminal -p /color-bold-use-default -n -t bool -s 'true'
                xfconf-query -c xfce4-terminal -p /tab-activity-color -n -t string -s '#db2777'
                xfconf-query -c xfce4-terminal -p /color-palette -n -t string -s '#000000;#cd3131;#0dbc79;#e5e510;#2472c8;#bc3fbc;#11a8cd;#e5e5e5;#666666;#f14c4c;#23d18b;#f5f543;#3b8eea;#d670d6;#29b8db;#e5e5e5'
                ;;
        esac
    fi
}

t3-theme() {
    case "${1:-}" in
        light | dark)
            mkdir -p "${_t3_chat_mode_file%/*}" && printf '%s\n' "$1" > "$_t3_chat_mode_file" || return
            [ -z "${T3_CHAT_MODE:-}" ] || echo "T3_CHAT_MODE=$T3_CHAT_MODE still overrides this in new shells" >&2
            T3_CHAT_MODE= _t3_chat_apply
            _t3_chat_apps "$1"
            echo "T3 Chat $1 is on, and new shells start in $1. VS Code has its own switch: Ctrl+K Ctrl+T."
            ;;
        '' | status) echo "T3 Chat $(_t3_chat_mode)" ;;
        *) echo 'usage: t3-theme [light|dark|status]' >&2; return 2 ;;
    esac
}

if [ -n "${ZSH_VERSION:-}" ]; then
    # Without truecolor, zsh maps the hex colors to the nearest of 256.
    case "${COLORTERM:-}" in truecolor | 24bit) ;; *) zmodload zsh/nearcolor 2>/dev/null ;; esac
    # Apply at the first prompt: Powerlevel10k's instant prompt forbids output during startup.
    _t3_chat_first_prompt() {
        _t3_chat_apply
        precmd_functions=(${precmd_functions:#_t3_chat_first_prompt})
    }
    precmd_functions+=(_t3_chat_first_prompt)
else
    _t3_chat_apply
fi
